def matchesRepeatPattern(s, p):
    n = len(s)
    full = (1 << n) - 1
    masks = {}
    for i, ch in enumerate(s):
        masks[ch] = masks.get(ch, 0) | (1 << i)
    cur = 1
    i = 0
    while i < len(p):
        c = p[i]
        i += 1
        if i < len(p) and p[i] == '{':
            lo = int(p[i + 1])
            hi = int(p[i + 3])
            i += 5
        else:
            lo = hi = 1
        mask = full if c == '.' else masks.get(c, 0)
        new = cur if lo == 0 else 0
        x = cur
        for k in range(1, hi + 1):
            x = (x & mask) << 1
            if not x:
                break
            if k >= lo:
                new |= x
        cur = new
        if not cur:
            return False
    return bool((cur >> n) & 1)
